const body = $json.body ?? $json;
const data = body.input?.data ?? {};
const expectedType = data.expectedOutput?.type;
const binding = data.outputBinding ?? {};
const title = data.input?.title ?? data.title ?? 'Generated draft';
const collection = binding.collection ?? 'pages';
const payloadSite = binding.payloadSite ?? 'primary';
const operation = binding.operation ?? 'create';
const resumeURL = data.input?.resumeURL ?? $execution.resumeUrl;
if (data.input?.demoApproval && resumeURL) {
  return [{
    json: {
      requestID: body.requestID,
      status: 'waiting',
      content: 'Waiting for approval in Payload.',
      approval: {
        title: 'Review structured plan task',
        prompt: `Approve ${data.taskID ?? 'this task'} before continuing?`,
        resumeURL,
      },
      n8nExecutionID: $execution.id,
    },
  }];
}
const output = expectedType === 'cms-draft'
  ? {
      target: {
        payloadSite,
        collection,
        operation,
      },
      document: {
        title,
      },
      mediaRequests: [],
    }
  : {
      taskID: data.taskID,
      title: data.title,
      receivedInput: data.input ?? {},
      instructionsLength: String(data.instructions ?? '').length,
    };
return [{
  json: {
    requestID: body.requestID,
    status: 'succeeded',
    output,
    summary: `Completed ${data.taskID ?? 'task'} for plan ${data.planID ?? 'unknown'}`,
    n8nExecutionID: $execution.id,
  },
}];
